struct Resource {};
struct CustomDeleter {
    void operator()(Resource* p) const { delete p; }
};

// unique_ptr holds the pointer and the (often optimized) empty Deleter.
using Ptr = std::unique_ptr<Resource, CustomDeleter>;

Ptr u(new Resource);

// All relational operators (<, <=, >, >=) are defined between unique_ptr and nullptr.
// They operate directly on the internal raw pointer u.get().

bool is_null_or_less = (u <= nullptr); // False (u.get() != 0)

u.reset(); // Internal raw pointer set to nullptr

// The comparison forces access to the internal state, avoiding virtual calls
// or expensive full deleter instantiation checks at runtime.
bool is_truly_null = (u <= nullptr); // True (u.get() == 0)
